CREATE TABLE app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE TABLE classes (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE TABLE students (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, display_name TEXT NOT NULL, raw_student_number TEXT NOT NULL, normalized_student_number TEXT NOT NULL, is_temporary INTEGER NOT NULL CHECK(is_temporary IN (0,1)), approved_at_utc TEXT NOT NULL, UNIQUE(class_id, normalized_student_number));
CREATE TABLE pending_student_requests (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, display_name TEXT NOT NULL, raw_student_number TEXT NOT NULL, normalized_student_number TEXT NOT NULL, requested_at_utc TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected')), resolved_at_utc TEXT NULL);
CREATE UNIQUE INDEX pending_student_unique ON pending_student_requests(class_id, normalized_student_number) WHERE status = 'pending';
CREATE TABLE teacher_sessions (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, created_at_utc TEXT NOT NULL, last_seen_at_utc TEXT NOT NULL, absolute_expires_at_utc TEXT NOT NULL, idle_expires_at_utc TEXT NOT NULL, revoked_at_utc TEXT NULL);
CREATE TABLE student_sessions (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE, class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, created_at_utc TEXT NOT NULL, last_seen_at_utc TEXT NOT NULL, absolute_expires_at_utc TEXT NOT NULL, idle_expires_at_utc TEXT NOT NULL, revoked_at_utc TEXT NULL);
CREATE UNIQUE INDEX active_student_session_unique ON student_sessions(student_id) WHERE revoked_at_utc IS NULL;
CREATE TABLE question_templates (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('single_choice','multiple_choice','short_text')), prompt TEXT NOT NULL, reference_answer TEXT NULL, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE TABLE question_template_options (id TEXT PRIMARY KEY, template_id TEXT NOT NULL REFERENCES question_templates(id) ON DELETE CASCADE, option_key TEXT NOT NULL, label TEXT NOT NULL, ordinal INTEGER NOT NULL, UNIQUE(template_id, option_key), UNIQUE(template_id, ordinal));
CREATE TABLE questions (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, template_id TEXT NULL REFERENCES question_templates(id) ON DELETE SET NULL, kind TEXT NOT NULL CHECK(kind IN ('single_choice','multiple_choice','short_text')), prompt TEXT NOT NULL, reference_answer TEXT NULL, state TEXT NOT NULL CHECK(state IN ('draft','open','closed')), opened_at_utc TEXT NULL, closed_at_utc TEXT NULL, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL, CHECK((state = 'draft' AND opened_at_utc IS NULL AND closed_at_utc IS NULL) OR (state = 'open' AND opened_at_utc IS NOT NULL AND closed_at_utc IS NULL) OR (state = 'closed' AND opened_at_utc IS NOT NULL AND closed_at_utc IS NOT NULL)));
CREATE TABLE question_options (id TEXT PRIMARY KEY, question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, option_key TEXT NOT NULL, label TEXT NOT NULL, ordinal INTEGER NOT NULL, UNIQUE(question_id, option_key), UNIQUE(question_id, ordinal));
CREATE TABLE answer_current (id TEXT PRIMARY KEY, question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE, revision INTEGER NOT NULL CHECK(revision >= 0), idempotency_key TEXT NOT NULL, payload_json TEXT NOT NULL, submitted_at_utc TEXT NOT NULL, late INTEGER NOT NULL CHECK(late IN (0,1)), UNIQUE(question_id, student_id));
CREATE TABLE answer_at_close (question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE, revision INTEGER NULL, submitted_at_utc TEXT NULL, payload_json TEXT NULL, no_answer INTEGER NOT NULL CHECK(no_answer IN (0,1)), closed_at_utc TEXT NOT NULL, PRIMARY KEY(question_id, student_id), CHECK((no_answer = 1 AND payload_json IS NULL) OR (no_answer = 0 AND payload_json IS NOT NULL)));
CREATE TABLE question_result_snapshots (question_id TEXT PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE, closed_at_utc TEXT NOT NULL, counts_json TEXT NOT NULL, short_text_response_count INTEGER NOT NULL CHECK(short_text_response_count >= 0));
CREATE TABLE answer_deletion_markers (question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE, deleted_at_utc TEXT NOT NULL, PRIMARY KEY(question_id, student_id));
CREATE TABLE answer_submission_idempotency (student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE, question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, request_fingerprint TEXT NOT NULL, answer_id TEXT NULL REFERENCES answer_current(id) ON DELETE SET NULL, response_json TEXT NOT NULL, outcome_code TEXT NOT NULL, created_at_utc TEXT NOT NULL, expires_at_utc TEXT NOT NULL, PRIMARY KEY(student_id, question_id, idempotency_key));
CREATE TABLE file_submission_tasks (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','open','closed')), max_bytes INTEGER NOT NULL CHECK(max_bytes = 100000000), deadline_at_utc TEXT NOT NULL, opened_at_utc TEXT NULL, closed_at_utc TEXT NULL, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE TABLE upload_sessions (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES file_submission_tasks(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','staging','validating','file_committed','metadata_committed','recovery_pending','failed')), staging_key TEXT NULL, final_storage_key TEXT NULL, bytes_received INTEGER NOT NULL DEFAULT 0 CHECK(bytes_received >= 0), sha256 TEXT NULL CHECK(sha256 IS NULL OR length(sha256) = 64), received_complete_at_utc TEXT NULL, error_code TEXT NULL, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE TABLE upload_idempotency (student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE, task_id TEXT NOT NULL REFERENCES file_submission_tasks(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, request_fingerprint TEXT NOT NULL, upload_session_id TEXT NULL REFERENCES upload_sessions(id) ON DELETE SET NULL, response_json TEXT NOT NULL, outcome_code TEXT NOT NULL, created_at_utc TEXT NOT NULL, expires_at_utc TEXT NOT NULL, PRIMARY KEY(student_id, task_id, idempotency_key));
CREATE TABLE file_submissions (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES file_submission_tasks(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE, original_filename TEXT NOT NULL, display_filename TEXT NOT NULL, storage_key TEXT NOT NULL UNIQUE, declared_mime_type TEXT NULL, byte_length INTEGER NOT NULL CHECK(byte_length >= 0 AND byte_length <= 100000000), sha256 TEXT NOT NULL CHECK(length(sha256) = 64), received_complete_at_utc TEXT NOT NULL, deleted_at_utc TEXT NULL);
CREATE UNIQUE INDEX valid_file_submission_unique ON file_submissions(task_id, student_id) WHERE deleted_at_utc IS NULL;
CREATE TABLE file_deletion_markers (submission_id TEXT PRIMARY KEY, task_id TEXT NOT NULL, student_id TEXT NOT NULL, deleted_at_utc TEXT NOT NULL, deletion_error_code TEXT NULL);
